import unittest

import models
import recommender
import support


class BaselineScoringTests(unittest.TestCase):
    """Verify the M3 formula, independent favorite bonuses and inclusive filter semantics."""

    def test_baseline_is_explicit(self):
        """Reject a supplied model instead of silently claiming to use its predictions."""
        scorer = recommender.Recommender(None, [])
        self.assertIsNone(scorer.model)
        with self.assertRaises(ValueError):
            recommender.Recommender(object(), [])

    def test_focus_changes_scores(self):
        """Give the same candidate the exact specified base and matching-focus scores."""
        event = support.event()
        career = models.UserProfile(1, 'Alex', 'ALEX23', {'career'})
        sports = models.UserProfile(2, 'Lena', 'LENA23', {'sports'})
        self.assertAlmostEqual(recommender.heuristic_score(event, career, 0), 0.70)
        self.assertAlmostEqual(recommender.heuristic_score(event, sports, 0), 0.40)

    def test_favorite_and_total_caps(self):
        """Cap three independent favorite bonuses at 0.25 and the total score at one."""
        event = support.event(club_id=7)
        profile = models.UserProfile(1, 'Alex', 'ALEX23', {'career'}, {1}, {7}, {'career_tech'})
        self.assertAlmostEqual(recommender.favorite_boost(event, profile), 0.25)
        self.assertAlmostEqual(recommender.heuristic_score(event, profile, 10), 1.0)
        profile.favorite_bundle_keys.clear()
        self.assertAlmostEqual(recommender.favorite_boost(event, profile), 0.20)

    def test_friend_bonus_validation(self):
        """Use 0.05 per friend up to 0.10, rejecting invalid counts."""
        event = support.event()
        profile = models.UserProfile(1, 'Alex', 'ALEX23', {'sports'})
        for count, expected in [(0, 0.40), (1, 0.45), (2, 0.50), (100, 0.50)]:
            self.assertAlmostEqual(recommender.heuristic_score(event, profile, count), expected)
        for invalid in (-1, True, 1.5):
            with self.assertRaises(ValueError):
                recommender.heuristic_score(event, profile, invalid)

    def test_sorted_scores_stable_ties_and_reasons(self):
        """Rank favorites first, preserve tie order and cap explanatory reasons at three."""
        events = [support.event(event_id=i, series_id=i, club_id=7) for i in (1, 2, 3)]
        profile = models.UserProfile(1, 'Alex', 'ALEX23', {'career'}, {2}, {7}, {'career_tech'})
        scored = recommender.Recommender().score_events(events, profile)
        self.assertEqual([item.event.event_id for item in scored], [2, 1, 3])
        self.assertEqual(scored[0].reasons,
                         ['Favorite course/series', 'Favorite club', 'Favorite category'])
        self.assertTrue(all(0 <= item.score <= 1 for item in scored))

    def test_filters_use_or_and_preserve_order(self):
        """Combine favorite and bundle matches with OR; clearing returns all candidates."""
        events = [support.event(event_id=1, series_id=1),
                  support.event(event_id=2, series_id=2, bundle_key='career_finance'),
                  support.event(event_id=3, series_id=3, bundle_key='career_consulting')]
        profile = models.UserProfile(1, 'Alex', 'ALEX23', {'career'}, {1})
        scored = recommender.Recommender().score_events(events, profile)
        filtered = recommender.filter_suggestions(scored, profile, {'career_finance'}, True)
        self.assertEqual([item.event.event_id for item in filtered], [1, 2])
        self.assertEqual(recommender.filter_suggestions(scored, profile), scored)
        only_favorites = recommender.filter_suggestions(scored, profile, favorites=True)
        self.assertEqual([item.event.event_id for item in only_favorites], [1])
        self.assertEqual(recommender.filter_suggestions(scored, profile, {'missing'}), [])
